import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMvcData(){const e=readFileSync(resolve(__dirname,"../../frontend/maha-vir-chakra-explorer/mvc-data.js"),"utf-8");return new Function(e+"\nreturn { MVC_INFO, MVC_HISTORY, MVC_ELIGIBILITY, MVC_MEDAL_DESIGN, MVC_OPERATIONS, MVC_AWARDEES, MVC_TIMELINE, MVC_FACTS };")()}describe("Maha Vir Chakra Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadMvcData()}),describe("MVC_INFO metadata",()=>{it("contains correct award metadata and statistics",()=>{expect(e.MVC_INFO.id).toBe("maha-vir-chakra"),expect(e.MVC_INFO.totalRecipients).toBe(218),expect(e.MVC_INFO.barToMvcRecipients).toBe(6),expect(Array.isArray(e.MVC_INFO.quickStats)).toBe(!0),expect(e.MVC_INFO.quickStats.length).toBe(6)})}),describe("MVC_HISTORY & MEDAL_DESIGN",()=>{it("contains overview, wartime significance, and silver medal design specs",()=>{expect(e.MVC_HISTORY.overview).toBeDefined(),expect(e.MVC_HISTORY.wartimeSignificance).toBeDefined(),expect(e.MVC_MEDAL_DESIGN.obverse).toContain("Five-pointed"),expect(e.MVC_MEDAL_DESIGN.ribbon).toContain("half-orange")})}),describe("MVC_AWARDEES catalog",()=>{it("contains iconic awardees including Major Chewang Rinchen, Brigadier Rajinder Singh, and Colonel Santosh Babu",()=>{expect(Array.isArray(e.MVC_AWARDEES)).toBe(!0),expect(e.MVC_AWARDEES.length).toBeGreaterThanOrEqual(5);const t=e.MVC_AWARDEES.find(e=>"chewang-rinchen"===e.id),a=e.MVC_AWARDEES.find(e=>"rajinder-singh"===e.id),i=e.MVC_AWARDEES.find(e=>"santosh-babu-mvc"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(i).toBeDefined(),expect(t.conflict).toContain("Bar to MVC"),expect(a.famousWords).toContain("last man and last bullet")})}),describe("MVC_TIMELINE & FACTS",()=>{it("has timeline milestones and interesting facts",()=>{expect(Array.isArray(e.MVC_TIMELINE)).toBe(!0),expect(e.MVC_TIMELINE.length).toBeGreaterThanOrEqual(6),expect(Array.isArray(e.MVC_FACTS)).toBe(!0),expect(e.MVC_FACTS.length).toBe(6)})}),describe("Landing Page Integration",()=>{it("is integrated into awards-of-india-explorer landing page",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("../maha-vir-chakra-explorer/index.html"),expect(e).toContain("Maha Vir Chakra")})})});